using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Simulates web search results. Replace with a real search API (e.g., Bing Search API) for production use.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    public static async Task<string> SearchAsync(string query)
    {
        // In production, use Bing Search API or similar:
        // var apiKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
        // var response = await HttpClient.GetAsync($"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}");

        // For demonstration, return simulated search results
        await Task.Delay(100); // Simulate network latency

        var results = new[]
        {
            new SearchResult($"Overview of {query}", $"https://example.com/{Uri.EscapeDataString(query)}",
                $"A comprehensive overview covering the key aspects of {query}, including recent developments and historical context."),
            new SearchResult($"{query} - Latest Research", $"https://research.example.com/{Uri.EscapeDataString(query)}",
                $"Recent academic and industry research findings related to {query}. Includes peer-reviewed studies and expert analysis."),
            new SearchResult($"Practical Applications of {query}", $"https://applied.example.com/{Uri.EscapeDataString(query)}",
                $"Real-world applications and use cases of {query} across various industries and domains."),
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

public record SearchResult(string Title, string Url, string Snippet);

namespace ResearchAgent;

public sealed class NoteService
{
    private readonly List<ResearchNote> _notes = [];

    public string SaveNote(string title, string content)
    {
        var note = new ResearchNote(title, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note saved: '{title}' ({content.Length} characters)";
    }

    public IReadOnlyList<ResearchNote> GetAllNotes() => _notes.AsReadOnly();
}

public record ResearchNote(string Title, string Content, DateTime SavedAt);

