 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Hosting;
 using Microsoft.Agents.AI;
 using OpenAI;
 using ResearchAgent;

 var builder = Host.CreateApplicationBuilder(args);

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable to run the research agent.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 builder.Services.AddChatClient(sp =>
     new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient());

 builder.Services.AddSingleton<NoteService>();

 using var host = builder.Build();

 var chatClient = host.Services.GetRequiredService<IChatClient>();
 var noteService = host.Services.GetRequiredService<NoteService>();

 // Define tools available to the agent
 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         (string query) => WebSearchTool.SearchAsync(query),
         "web_search",
         "Searches the web for information on a given query. Returns a list of relevant results with titles and snippets."),

     AIFunctionFactory.Create(
         (string title, string content) => noteService.SaveNote(title, content),
         "save_note",
         "Saves a research note with a title and content for later reference."),

     AIFunctionFactory.Create(
         () => noteService.GetAllNotes(),
         "get_notes",
         "Retrieves all saved research notes.")
 };

 // Configure agent chat options
 var agentOptions = new ChatClientAgentOptions
 {
     ChatOptions = new ChatOptions
     {
         Temperature = 0f,
         MaxOutputTokens = 2048,
         Tools = [.. tools],
     },
 };

 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     instructions: """
         You are a research agent. Your job is to research a topic thoroughly by:
         1. Searching the web for relevant information using the web_search tool
         2. Saving important findings as notes using the save_note tool
         3. After gathering enough information, retrieve your notes with get_notes and provide a comprehensive summary

         Always search for multiple aspects of the topic and save key findings before summarizing.
         """,
     tools: tools,
     loggerFactory: null,
     serviceProvider: null);

 // Get the research topic
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: {topic}\n");
 Console.WriteLine(new string('-', 50));

 // Run the agent
 var session = await agent.CreateSessionAsync();

 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session))
 {
     Console.Write(update.Text);
 }

 Console.WriteLine();
 Console.WriteLine(new string('-', 50));
 Console.WriteLine("\n--- Saved Research Notes ---");
 foreach (var note in noteService.GetAllNotes())
 {
     Console.WriteLine($"\n[{note.Title}]\n{note.Content}\n");
 }

